def transform(grid):
    # The four 3x3 tiles represent colored patterns; the tile whose pattern
    # is independent is the tile at top-right. Return its exact matrix.
    # Locate connected nonzero components, then identify top-right component.
    R,C=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(R):
      for c in range(C):
        if grid[r][c] and (r,c) not in seen:
          q=[(r,c)];seen.add((r,c)); cells=[]
          while q:
            x,y=q.pop();cells.append((x,y))
            for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
              if 0<=nx<R and 0<=ny<C and grid[nx][ny] and (nx,ny) not in seen:
                seen.add((nx,ny));q.append((nx,ny))
          comps.append(cells)
    # Component bounding boxes are each 3x3 tiles; output is top-right tile.
    boxes=[]
    for comp in comps:
      r0=min(x for x,y in comp);r1=max(x for x,y in comp);c0=min(y for x,y in comp);c1=max(y for x,y in comp)
      boxes.append((r0,c0,r1,c1))
    r0,c0,r1,c1=max(boxes,key=lambda b:(-b[0],b[1]))
    # The target (output) is the tile with same structure as upper-right target;
    # in this arrangement it is the tile whose cells form the only pattern at
    # the upper-right among source tiles. Return its 3x3 bounding box.
    # Identify individual 3x3 block by component row/column location.
    return [row[c0:c0+3] for row in grid[r0:r0+3]]
